const prefs = $('Load User Preferences').all();
const history = $('Load Recent Meals').all();

// Parse preferences (expecting key-value rows)
const prefMap = {};
for (const row of prefs) {
  const key = row.json.setting || row.json.key;
  const val = row.json.value;
  if (key && val !== undefined) prefMap[key.toLowerCase().replace(/\s+/g, '_')] = val;
}

// Last 14 days of meals to avoid repetition
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 14);
const recentMeals = history
  .filter(r => r.json.date && new Date(r.json.date) >= cutoff)
  .map(r => r.json.meal_name)
  .filter(Boolean);

const uniqueRecent = [...new Set(recentMeals)];

return [{
  json: {
    people: parseInt(prefMap.household_size) || 2,
    dietaryRestrictions: prefMap.dietary_restrictions || 'none',
    cuisinePreferences: prefMap.cuisine_preferences || 'varied',
    dislikedIngredients: prefMap.disliked_ingredients || 'none',
    cookingTimeWeekday: prefMap.weekday_cooking_time || '30 minutes',
    cookingTimeWeekend: prefMap.weekend_cooking_time || '60 minutes',
    budget: prefMap.weekly_budget || 'moderate',
    includeBreakfast: (prefMap.include_breakfast || 'no').toLowerCase() === 'yes',
    includeLunch: (prefMap.include_lunch || 'no').toLowerCase() === 'yes',
    recentMeals: uniqueRecent.slice(0, 20),
    weekStartDate: new Date().toISOString().split('T')[0]
  }
}];

