Plan a week of dinners (Monday–Sunday) for {{ $json.people }} people.

Constraints:
- Dietary restrictions: {{ $json.dietaryRestrictions }}
- Disliked ingredients: {{ $json.dislikedIngredients }}
- Cuisine preferences: {{ $json.cuisinePreferences }}
- Weekday cooking time: {{ $json.cookingTimeWeekday }}
- Weekend cooking time: {{ $json.cookingTimeWeekend }}
- Budget: {{ $json.budget }}
{{ $json.includeLunch ? '- Include lunch suggestions for each day' : '' }}
{{ $json.includeBreakfast ? '- Include breakfast suggestions Mon–Fri' : '' }}

Do NOT repeat these recent meals: {{ $json.recentMeals.length ? $json.recentMeals.join(', ') : 'none to avoid' }}

Respond with this exact JSON structure:
{
  "week_of": "{{ $json.weekStartDate }}",
  "people": {{ $json.people }},
  "days": [
    {
      "day": "Monday",
      "dinner": {
        "name": "Meal name",
        "description": "One sentence. What it is, why it works for this day.",
        "prep_time_minutes": 25,
        "cook_time_minutes": 20,
        "servings": {{ $json.people }},
        "ingredients": [
          { "item": "chicken thighs", "quantity": "500g" }
        ],
        "key_steps": ["Step 1", "Step 2", "Step 3"]
      }
    }
  ],
  "grocery_list": {
    "produce": [ { "item": "cherry tomatoes", "quantity": "250g" } ],
    "protein": [],
    "dairy": [],
    "pantry": [],
    "other": []
  },
