const rawText = $input.first().json.text || $input.first().json.content?.[0]?.text || '';

let plan;
try {
  const clean = rawText.replace(/```json|```/g, '').trim();
  plan = JSON.parse(clean);
} catch(e) {
  return [{ json: { error: 'Parse error', raw: rawText, message: e.message } }];
}

return [{ json: plan }];

const plan = $input.first().json;
const days = plan.days || [];

function escHtml(s) { return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const dayColors = ['#e8f4e8','#e8eef8','#f8f0e8','#f0e8f8','#f8f8e8','#e8f4f4','#f8e8e8'];

const mealCards = days.map((d, i) => {
  const dinner = d.dinner || {};
  const totalMins = (dinner.prep_time_minutes || 0) + (dinner.cook_time_minutes || 0);
  const ingredients = (dinner.ingredients || []).map(ing =>
    `<li style="font-size:13px;margin-bottom:3px">${escHtml(ing.quantity)} ${escHtml(ing.item)}</li>`
  ).join('');
  const steps = (dinner.key_steps || []).map((s, j) =>
    `<li style="font-size:13px;margin-bottom:5px;line-height:1.5">${escHtml(s)}</li>`
  ).join('');
  return `
    <div style="background:${dayColors[i]};border-radius:8px;padding:18px 20px;margin-bottom:14px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <strong style="font-size:13px;text-transform:uppercase;letter-spacing:0.5px;color:#555">${escHtml(d.day)}</strong>
        <span style="font-size:12px;color:#777;font-family:monospace">${totalMins > 0 ? totalMins + ' min total' : ''}</span>
      </div>
      <div style="font-size:17px;font-weight:600;margin-bottom:5px">${escHtml(dinner.name)}</div>
      <div style="font-size:14px;color:#444;margin-bottom:12px;line-height:1.5">${escHtml(dinner.description)}</div>
      <details style="cursor:pointer">
        <summary style="font-size:12px;color:#666;font-weight:600;outline:none">Ingredients + steps</summary>
        <div style="margin-top:10px;display:grid;grid-template-columns:1fr 1fr;gap:12px">
          <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#888;margin-bottom:4px">Ingredients</div><ul style="list-style:disc;padding-left:16px;margin:0">${ingredients}</ul></div>
          <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#888;margin-bottom:4px">How to make it</div><ol style="padding-left:16px;margin:0">${steps}</ol></div>
        </div>
      </details>
    </div>`;
}).join('');

// grocery list
const grocery = plan.grocery_list || {};
const grocerySections = Object.entries(grocery).map(([cat, items]) => {
  if (!items || !items.length) return '';
  const itemList = items.map(i => `<li style="font-size:14px;margin-bottom:4px">☐ ${escHtml(i.quantity)} ${escHtml(i.item)}</li>`).join('');
  return `<div style="margin-bottom:18px"><div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">${escHtml(cat)}</div><ul style="list-style:none;padding:0;margin:0">${itemList}</ul></div>`;
}).join('');

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#fafaf8;color:#1a1a1a;margin:0;padding:20px">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#2d5a27;color:#fff;padding:22px 28px;border-radius:10px 10px 0 0">
    <h1 style="margin:0;font-size:20px;font-weight:600">🥘 Meal Plan — Week of ${escHtml(plan.week_of)}</h1>
    <div style="color:#a8d5a2;font-size:13px;margin-top:4px">For ${escHtml(String(plan.people))} people</div>
  </div>
  <div style="background:#fff;padding:24px 28px;border-radius:0 0 10px 10px;box-shadow:0 2px 8px rgba(0,0,0,0.06)">
    ${mealCards}

    ${plan.meal_prep_tip ? `<div style="background:#f0f7ee;border-left:3px solid #2d5a27;padding:14px 18px;margin:20px 0;border-radius:0 6px 6px 0;font-size:14px;line-height:1.6"><strong>Weekend prep tip:</strong> ${escHtml(plan.meal_prep_tip)}</div>` : ''}

    ${plan.ingredient_overlaps && plan.ingredient_overlaps.length ? `<div style="background:#fafaf0;border:1px solid #e8e4c8;padding:14px 18px;border-radius:6px;margin-bottom:20px"><div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#888;margin-bottom:8px">Ingredient overlaps</div>${plan.ingredient_overlaps.map(o => `<div style="font-size:13px;color:#555;margin-bottom:4px">→ ${escHtml(o)}</div>`).join('')}</div>` : ''}

    <h2 style="font-size:16px;margin:24px 0 16px;border-bottom:2px solid #e8e4df;padding-bottom:6px">🛒 Grocery List</h2>
    <div style="columns:2;gap:24px">${grocerySections}</div>
  </div>
  <div style="text-align:center;font-size:11px;color:#aaa;margin-top:14px;font-family:monospace">Generated ${new Date().toLocaleDateString()} · Weekly Meal Planner Agent</div>
</div>
</body></html>`;

return [{ json: { html, plan, subject: `Your meal plan for the week of ${plan.week_of}` } }];
